\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{calc}
\pagestyle{empty}

% ── Dark-mode Developer-Tool Color Theme ──
\definecolor{primary}{HTML}{0F172A}       % deep navy background
\definecolor{secondary}{HTML}{1E293B}     % card bg / slate
\definecolor{accent}{HTML}{38BDF8}        % electric blue
\definecolor{teal}{HTML}{2DD4BF}          % teal
\definecolor{amber}{HTML}{FBBF24}         % amber warning
\definecolor{amberwarn}{HTML}{F59E0B}     % darker amber
\definecolor{redalert}{HTML}{F87171}      % red alert
\definecolor{bgposter}{HTML}{0B1120}      % poster background (darker navy)
\definecolor{cardbg}{HTML}{111827}        % card background
\definecolor{cardbg2}{HTML}{1E293B}       % alternate card
\definecolor{textbright}{HTML}{F1F5F9}    % bright text
\definecolor{textdim}{HTML}{94A3B8}       % dim text
\definecolor{textmed}{HTML}{CBD5E1}       % medium text
\definecolor{accentbg}{HTML}{0C2D4A}      % blue tint bg
\definecolor{tealbg}{HTML}{0C2F2A}        % teal tint bg
\definecolor{amberbg}{HTML}{3D2806}       % amber tint bg
\definecolor{redbg}{HTML}{3A1212}         % red tint bg

\pagecolor{bgposter}
\color{textbright}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{teal}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{22}{28}\selectfont\color{textdim}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe, dark mode) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=6pt, boxrule=1pt, colback=cardbg, colframe=secondary,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=accentbg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.25},
  },
  tealcard/.style={
    enhanced, arc=6pt, boxrule=1pt, colback=cardbg, colframe=secondary,
    borderline west={6pt}{0pt}{teal},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=tealbg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={teal!50},
    valign=top, drop shadow={opacity=0.25},
  },
  ambercard/.style={
    enhanced, arc=6pt, boxrule=1pt, colback=cardbg, colframe=secondary,
    borderline west={6pt}{0pt}{amber},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=amberbg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={amber!50},
    valign=top, drop shadow={opacity=0.25},
