    enhanced, arc=6pt, boxrule=1pt, colback=primary, colframe=accent,
    borderline west={8pt}{0pt}{accent},
    left=18pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=accentbg,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.35},
  },
