\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=2mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=accent, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4}
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{56}{68}\selectfont\bfseries\color{accent} JS Framework Benchmark}\\[8pt]
  {\fontsize{30}{38}\selectfont\color{textmed} 5 Years of Browser Performance Testing}\\[6pt]
  {\fontsize{22}{28}\selectfont\color{textdim} Chrome 55 \textrightarrow{} Chrome 146 \quad|\quad 2017 -- 2026 \quad|\quad github.com/krausest/js-framework-benchmark}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=secondary, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{accent!40},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accent!40}{accentbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{accent} 60+}\\[4pt]
      {\fontsize{20}{26}\selectfont\color{textmed} Official Runs}\vspace{6pt}%
    }}
  \end{minipage}\hfill
