      {\fontsize{20}{26}\selectfont\color{textmed} Continuous Tracking}\vspace{6pt}%
    }}
  \end{minipage}
}

% ══ COLUMN 1 ══
\posterbox[bluecard, title={What Is the JS Framework Benchmark?}
]{name=overview, column=1, between=row5 and row11}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Open-source benchmark comparing JS web frameworks
    \item Real-world DOM ops: create 1,000 rows, updates, selection, swap, removal
    \item Controlled Chrome + CPU throttling
    \item Maintained by Stefan Krause on GitHub
  \end{itemize}
  \vspace{8pt}
  \colorbox{accentbg}{\parbox{0.94\linewidth}{%
    \centering\fontsize{22}{28}\selectfont\color{textmed}
    Most widely referenced yardstick for JS framework performance
  }}
}

\posterbox[tealcard, title={Platform Coverage}
]{name=coverage, column=1, between=row11 and row16}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{95\%+} of runs on \textbf{macOS (OSX)}
    \item Only 2 Windows runs: Chrome 104 (2022) \& Chrome 121 (2024)
    \item Primarily reflects macOS + Chrome performance
  \end{itemize}
  \vspace{6pt}
  \posterfig{0.92}{figures/platform.png}{Platform breakdown: macOS dominates the dataset}
}

\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=1, between=row16 and bottom}{
  \fontsize{24}{32}\selectfont
  \begin{enumerate}[itemsep=10pt]
    \item Compare \textbf{within the same Chrome version}
    \item Consult \textbf{Chrome 146} for latest standings
    \item Understand \textbf{keyed vs non-keyed} modes
    \item 60+ data points = longest-running JS perf tracker
  \end{enumerate}
}

% ══ COLUMN 2 ══
\posterbox[tealcard, title={Benchmark Timeline: Chrome 55 \textrightarrow{} 146}
]{name=timeline, column=2, between=row5 and row14}{
  \posterfig{0.96}{figures/timeline.png}{8 years of official benchmark runs from 2017 to 2026}
}

\posterbox[ambercard, title={Methodology Milestones}
]{name=methodology, column=2, between=row14 and bottom}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Chrome 118 (2023):} weighted geometric mean replaces arithmetic mean
    \item CPU throttling recalibrated for realistic load
    \item Ongoing timing / driver instrumentation refinements
    \item \textbf{Chrome 139+:} odd versions = keyed frameworks only
  \end{itemize}
  \vspace{6pt}
  \colorbox{amberbg}{\parbox{0.94\linewidth}{%
    \centering\fontsize{22}{28}\selectfont\color{amber}
    \textbf{Warning:} cross-version comparisons are unreliable
  }}
}

% ══ COLUMN 3 ══
\posterbox[ambercard, title={Why Cross-Version Comparisons Break}
]{name=whybreak, column=3, between=row5 and row11}{
  \posterfig{0.96}{figures/methodology.png}{Methodology changes that invalidate direct score comparisons}
}

\posterbox[bluecard, title={Runs by Year}
]{name=runsbyyear, column=3, between=row11 and row17}{
  \fontsize{22}{30}\selectfont
  \renewcommand{\arraystretch}{1.8}
  \begin{tabular}{@{}l c c@{}}
    \textbf{Year} & \textbf{Runs} & \textbf{Chrome} \\
    \midrule
    \rowcolor{accentbg}
    2017--2019 & 4 & 55--69 \\
    2020 & 5 & 83--87 \\
    \rowcolor{accentbg}
    2021 & 9 & 88--96 \\
    2022 & 13 & 97--108 \\
    \rowcolor{accentbg}
    2023 & 12 & 109--120 \\
    2024 & 12 & 121--131 \\
    \rowcolor{accentbg}
    2025 & 12 & 132--143 \\
    2026 & 3 & 144--146 \\
  \end{tabular}
  \vspace{6pt}
  {\fontsize{20}{26}\selectfont\color{textdim} 2025 was the most active year with 12 runs}
}

\posterbox[highlightcard, title={Get the Data}
]{name=refs, column=3, between=row17 and bottom}{
  \fontsize{24}{32}\selectfont
  \centering
  \vspace{4pt}
  {\fontsize{28}{36}\selectfont\color{accent}\textbf{github.com/krausest}}\\[4pt]
  {\fontsize{22}{28}\selectfont\color{textdim}/js-framework-benchmark}\\[10pt]
  {\fontsize{20}{26}\selectfont\color{textmed} Latest run: Chrome 146 on macOS}
  \vspace{4pt}
}

\end{tcbposter}
\end{document}

